+            BTreeNode newRoot = new BTreeNode(minDegree, false);
+            newRoot.children[0] = root;
+            newRoot.splitChild(0, root);
+            int childIndex = newRoot.keys[0] < key ? 1 : 0;
+            newRoot.children[childIndex].insertNonFull(key);
+            root = newRoot;
+        } else {
+            root.insertNonFull(key);
+        }
+    }
